# Claude Cowork (Amazon Bedrock) - machine-wide installer for Windows.
#
# GENERATED by scripts/install/build-windows-cowork.sh for release 2026-07-16-160359. Do not edit by hand:
# regenerate, so the download hash and the policy values always come from the same build.
#
# Deploy as an Intune platform script (Devices > Scripts and remediations > Platform scripts):
#   Run this script using the logged on credentials : No   (runs as SYSTEM)
#   Run script in 64 bit PowerShell Host            : Yes  (else HKLM\SOFTWARE is redirected to WOW6432Node)
#   Enforce script signature check                  : per your policy (sign this file if Yes)
# Upload THIS file to Intune; do not fetch-and-execute it from a URL.
#
# What it does (nothing is written into any user's profile):
#   1. downloads the helper package and refuses it unless its SHA256 matches the value pinned below
#   2. installs it to C:\ProgramData\ccwb (owner Administrators; SYSTEM/Administrators full,
#      Users read+execute; the directory is created with this ACL, never inherited)
#   3. writes the Claude Desktop policy as REG_SZ values directly under HKLM\SOFTWARE\Policies\Claude,
#      remembering any value it overwrote so uninstall-cowork.ps1 can restore it
#   4. records release + package hash + policy digest in HKLM\SOFTWARE\ccwb; a re-run is a no-op only
#      when all three match
# Note: once any value exists under HKLM\SOFTWARE\Policies\Claude, Claude Desktop ignores HKCU policy.
#
# Test override (never set in production): CCWB_INSTALL_ROOT, CCWB_POLICY_KEY, CCWB_MARKER_KEY, CCWB_LOG.
#Requires -Version 5.1
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

$Release       = '2026-07-16-160359'
$PackageUrl    = 'https://raw.githubusercontent.com/theiconic/ClaudeCodeSetup/main/releases/2026-07-16-160359/ClaudeCowork-2026-07-16-160359-windows.zip'
$PackageSha256 = '08BFB77DBD0F5E594807F0CDAEDAA5EEDBD3A4CEC5875273E1848635AB3952D8'
$PolicyDigest  = '8FE84EB1D38409FB3A91B0AA2309B36C9D107C49EEAB4AD9709AFBD166D973FA'

function Get-Setting([string]$Name, [string]$Default) {
    $v = [Environment]::GetEnvironmentVariable($Name)
    if ([string]::IsNullOrEmpty($v)) { return $Default }
    return $v
}
# Logs go to an admin-only folder (Intune's own log folder when present, so IT log collection picks it up).
$ImeLogs = 'C:\ProgramData\Microsoft\IntuneManagementExtension\Logs'
if (Test-Path -LiteralPath $ImeLogs -PathType Container) { $DefaultLog = "$ImeLogs\ccwb-cowork.log" }
else { $DefaultLog = "$env:windir\Logs\ccwb-cowork.log" }
$InstallRoot = Get-Setting 'CCWB_INSTALL_ROOT' 'C:\ProgramData\ccwb'
$PolicyKey   = Get-Setting 'CCWB_POLICY_KEY'   'HKLM:\SOFTWARE\Policies\Claude'
$MarkerKey   = Get-Setting 'CCWB_MARKER_KEY'   'HKLM:\SOFTWARE\ccwb'
$LogFile     = Get-Setting 'CCWB_LOG'          $DefaultLog

# Claude Desktop policy, written as REG_SZ. Booleans are "true"/"false"; arrays are JSON strings.
$Policy = [ordered]@{
    'inferenceProvider'                   = 'bedrock'
    'inferenceBedrockRegion'              = 'ap-southeast-2'
    'inferenceBedrockProfile'             = 'theiconic-claude-primary'
    'inferenceModels'                     = '["global.anthropic.claude-opus-5-5", "global.anthropic.claude-sonnet-5-5", "global.anthropic.claude-haiku-5-5"]'
    'isClaudeCodeForDesktopEnabled'       = 'false'
    'isDesktopExtensionEnabled'           = 'true'
    'isDesktopExtensionDirectoryEnabled'  = 'true'
    'isDesktopExtensionSignatureRequired' = 'true'
    'isLocalDevMcpEnabled'                = 'true'
    'inferenceBedrockAwsDir'              = 'C:\ProgramData\ccwb\aws'
    'otlpEndpoint'                        = 'http://otel-collector-alb-1417639215.ap-southeast-2.elb.amazonaws.com'
    'otlpProtocol'                        = 'http/protobuf'
}

$RequiredFiles = @('credential-process-windows.exe', 'config.json', 'version.json', 'aws\config', 'aws\credentials')
# Owner Administrators; protected DACL: SYSTEM + Administrators full, Users read & execute, inherited by children.
$LockedSddl = 'O:BAG:BAD:PAI(A;OICI;FA;;;SY)(A;OICI;FA;;;BA)(A;OICI;0x1200a9;;;BU)'
$TrustedSids = @('S-1-5-18', 'S-1-5-32-544')
# Files extracted by an elevated admin (manual test run) are owned by that admin; also trusted as owner.
$TrustedOwners = $TrustedSids + @([Security.Principal.WindowsIdentity]::GetCurrent().User.Value)

function Write-Log([string]$Message) {
    $line = '{0} ccwb-cowork: {1}' -f (Get-Date -Format 's'), $Message
    Write-Output $line
    try { Add-Content -LiteralPath $LogFile -Value $line } catch { }  # a log we cannot write never aborts the install
}
function Stop-Install([string]$Message) { Write-Log "ERROR: $Message"; exit 1 }

# Null-safe registry read: StrictMode makes a missing property throw, GetValue returns $null instead.
function Get-RegValue([string]$Key, [string]$Name) {
    if (-not (Test-Path -LiteralPath $Key)) { return $null }
    return (Get-Item -LiteralPath $Key).GetValue($Name, $null, 'DoNotExpandEnvironmentNames')
}

# JSON array -> flat string[]. PS 5.1 ConvertFrom-Json emits an array as ONE object, so never wrap
# its output in @(...) (that nests it); enumerate it instead.
function ConvertFrom-JsonArray([string]$Json) {
    $out = New-Object System.Collections.Generic.List[string]
    if ($Json) { foreach ($x in ($Json | ConvertFrom-Json)) { $out.Add([string]$x) } }
    return ,$out.ToArray()
}
function ConvertFrom-JsonMap([string]$Json) {
    $map = @{}
    if ($Json) { foreach ($p in ($Json | ConvertFrom-Json).PSObject.Properties) { $map[$p.Name] = [string]$p.Value } }
    return $map
}

# Attributes of the path itself, without following a reparse point; $null if nothing is there.
function Get-OwnAttributes([string]$Path) {
    try { return [IO.File]::GetAttributes($Path) } catch [IO.FileNotFoundException], [IO.DirectoryNotFoundException] { return $null }
}

# rd /s never follows junctions or symlinks (it removes the link itself). Best effort; returns success.
function Remove-TreeQuietly([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path)) { return $true }
    $eap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    try { & cmd.exe /d /c rd /s /q "`"$Path`"" 2>&1 | Out-Null } finally { $ErrorActionPreference = $eap }
    return -not (Test-Path -LiteralPath $Path)
}

# Fails unless the owner is SYSTEM/Administrators and no other principal can write, delete or change ACLs.
function Assert-Locked([string]$Path) {
    $writeMask = [Security.AccessControl.FileSystemRights]'Write, Delete, DeleteSubdirectoriesAndFiles, ChangePermissions, TakeOwnership'
    foreach ($item in @(Get-Item -LiteralPath $Path -Force) + @(Get-ChildItem -LiteralPath $Path -Recurse -Force)) {
        if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { Stop-Install "reparse point: $($item.FullName)" }
        $acl = Get-Acl -LiteralPath $item.FullName
        $owner = $acl.GetOwner([Security.Principal.SecurityIdentifier]).Value
        if ($TrustedOwners -notcontains $owner) { Stop-Install "untrusted owner $owner on $($item.FullName)" }
        foreach ($ace in $acl.GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])) {
            if ($ace.AccessControlType -eq 'Allow' -and $TrustedSids -notcontains $ace.IdentityReference.Value -and
                ($ace.FileSystemRights -band $writeMask)) {
                Stop-Install "write access for $($ace.IdentityReference.Value) on $($item.FullName)"
            }
        }
    }
}

# --- 1. Preconditions -----------------------------------------------------------------------
if (-not [Environment]::Is64BitProcess) {
    Stop-Install 'running in 32-bit PowerShell: enable "Run script in 64 bit PowerShell Host" in Intune'
}
$principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Stop-Install 'must run as SYSTEM or an administrator ("Run this script using the logged on credentials" = No)'
}

if ((Get-RegValue $MarkerKey 'Release') -eq $Release -and
    (Get-RegValue $MarkerKey 'PackageSha256') -eq $PackageSha256 -and
    (Get-RegValue $MarkerKey 'PolicyDigest') -eq $PolicyDigest -and
    (Test-Path -LiteralPath (Join-Path $InstallRoot 'credential-process-windows.exe'))) {
    Write-Log "release $Release (package $PackageSha256) already installed; nothing to do"
    exit 0
}

$parent = Split-Path -Parent $InstallRoot
$leaf   = Split-Path -Leaf $InstallRoot
# Leftovers from an interrupted earlier run (best effort; a locked one is retried next run).
# Only real directories that we own are deleted: users can create entries with these names too.
foreach ($old in @(Get-ChildItem -LiteralPath $parent -Directory -Force -Filter "$leaf.staging-*") +
                 @(Get-ChildItem -LiteralPath $parent -Directory -Force -Filter "$leaf.old-*")) {
    if ($old.Attributes -band [IO.FileAttributes]::ReparsePoint) { continue }
    # A user-created entry may deny SYSTEM read access; skip it rather than abort the install.
    try { $oldOwner = (Get-Acl -LiteralPath $old.FullName).GetOwner([Security.Principal.SecurityIdentifier]).Value } catch { continue }
    if ($TrustedSids -notcontains $oldOwner) { continue }
    [void](Remove-TreeQuietly $old.FullName)
}

# --- 2. Download into a staging directory that is locked from the moment it exists ----------
$staging = Join-Path $parent ("$leaf.staging-" + [IO.Path]::GetRandomFileName())
if (Test-Path -LiteralPath $staging) { Stop-Install "staging path already exists: $staging" }
$sd = New-Object Security.AccessControl.DirectorySecurity
$sd.SetSecurityDescriptorSddlForm($LockedSddl)
[void][IO.Directory]::CreateDirectory($staging, $sd)
$moved = $false
try {
    Assert-Locked $staging   # CreateDirectory returns an existing directory silently; prove it is ours
    $zip = Join-Path $staging 'package.zip'
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    try {
        Invoke-WebRequest -Uri $PackageUrl -OutFile $zip -UseBasicParsing
    } catch {
        Stop-Install "download failed: $($_.Exception.Message)"
    }
    $hash = (Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash
    if ($hash -ne $PackageSha256) { Stop-Install "SHA256 mismatch for $PackageUrl (got $hash); refusing to install" }

    Expand-Archive -LiteralPath $zip -DestinationPath $staging
    Remove-Item -LiteralPath $zip -Force
    foreach ($f in $RequiredFiles) {
        if (-not (Test-Path -LiteralPath (Join-Path $staging $f) -PathType Leaf)) { Stop-Install "missing payload file: $f" }
    }
    $payloadRelease = (Get-Content -LiteralPath (Join-Path $staging 'version.json') -Raw | ConvertFrom-Json).release
    if ($payloadRelease -ne $Release) { Stop-Install "payload is release $payloadRelease, expected $Release" }
    Assert-Locked $staging

    # --- 3. Swap into place -----------------------------------------------------------------
    # Rename the current install aside first: it fails cleanly (nothing changed) while a helper
    # file is in use, and works whatever ACL a pre-existing directory has (SYSTEM holds
    # delete-child on ProgramData). A plain file squatting on the name is removed.
    # Attributes are read without following links, so a dangling junction is seen too.
    $aside = $null
    $attrs = Get-OwnAttributes $InstallRoot
    if ($null -ne $attrs) {
        if ($attrs -band [IO.FileAttributes]::ReparsePoint) {
            # Junction/symlink squatting on the name: remove the link only, never its target.
            if ($attrs -band [IO.FileAttributes]::Directory) { [IO.Directory]::Delete($InstallRoot, $false) }
            else { [IO.File]::Delete($InstallRoot) }
        } elseif (-not ($attrs -band [IO.FileAttributes]::Directory)) {
            try { Remove-Item -LiteralPath $InstallRoot -Force }
            catch { Stop-Install "a file is blocking ${InstallRoot}: $($_.Exception.Message)" }
        } else {
            $aside = Join-Path $parent ("$leaf.old-" + [IO.Path]::GetRandomFileName())
            try { [IO.Directory]::Move($InstallRoot, $aside) }
            catch { Stop-Install "current install is in use (Claude Desktop signing in?); retry later: $($_.Exception.Message)" }
        }
    }
    try {
        [IO.Directory]::Move($staging, $InstallRoot)   # throws if the target re-appeared meanwhile
        $moved = $true
    } catch {
        if ($aside) { try { [IO.Directory]::Move($aside, $InstallRoot) } catch { } }
        Stop-Install "could not move the new install into ${InstallRoot}: $($_.Exception.Message)"
    }
    Assert-Locked $InstallRoot
    if ($aside -and -not (Remove-TreeQuietly $aside)) { Write-Log "previous install left at $aside (in use); removed next run" }
} finally {
    if (-not $moved) { [void](Remove-TreeQuietly $staging) }
}

# --- 4. Claude Desktop policy (REG_SZ, directly under the key) ------------------------------
[string[]]$ours = ConvertFrom-JsonArray (Get-RegValue $MarkerKey 'PolicyNames')
$prior = ConvertFrom-JsonMap (Get-RegValue $MarkerKey 'PriorValues')

foreach ($name in $Policy.Keys) {
    $existing = Get-RegValue $PolicyKey $name
    if ($null -ne $existing -and $ours -notcontains $name -and -not $prior.ContainsKey($name)) {
        # Someone else set this value; keep it so uninstall can put it back. Restored as REG_SZ,
        # which Desktop accepts for every key (REG_DWORD/REG_MULTI_SZ type is not preserved).
        $prior[$name] = [string]$existing
        Write-Log "overwriting existing policy value $name (previous value saved for uninstall)"
    }
}
# Record ownership BEFORE writing values, so a crash mid-write never makes our own values look "prior".
if (-not (Test-Path -LiteralPath $MarkerKey)) { New-Item -Path $MarkerKey -Force | Out-Null }
[string[]]$recordNames = @($ours) + @($Policy.Keys | Where-Object { $ours -notcontains $_ })
New-ItemProperty -LiteralPath $MarkerKey -Name PolicyNames -Value (ConvertTo-Json -InputObject $recordNames -Compress) -PropertyType String -Force | Out-Null
New-ItemProperty -LiteralPath $MarkerKey -Name PriorValues -Value (ConvertTo-Json -InputObject $prior -Compress) -PropertyType String -Force | Out-Null

if (-not (Test-Path -LiteralPath $PolicyKey)) { New-Item -Path $PolicyKey -Force | Out-Null }
foreach ($name in $Policy.Keys) {
    New-ItemProperty -LiteralPath $PolicyKey -Name $name -Value ([string]$Policy[$name]) -PropertyType String -Force | Out-Null
}
# Values this installer wrote for an earlier release but no longer ships: restore or remove.
foreach ($old in $ours) {
    if (-not $Policy.Contains($old)) {
        if ($prior.ContainsKey($old)) {
            New-ItemProperty -LiteralPath $PolicyKey -Name $old -Value ([string]$prior[$old]) -PropertyType String -Force | Out-Null
            $prior.Remove($old)
        } else {
            Remove-ItemProperty -LiteralPath $PolicyKey -Name $old -ErrorAction SilentlyContinue
        }
    }
}

# --- 5. Marker (outside the Policies key); Release/hash/digest last = "install complete" -----
$marker = [ordered]@{
    Release       = $Release
    PackageSha256 = $PackageSha256
    PolicyDigest  = $PolicyDigest
    PolicyNames   = (ConvertTo-Json -InputObject @($Policy.Keys) -Compress)
    PriorValues   = (ConvertTo-Json -InputObject $prior -Compress)
}
foreach ($name in $marker.Keys) {
    New-ItemProperty -LiteralPath $MarkerKey -Name $name -Value ([string]$marker[$name]) -PropertyType String -Force | Out-Null
}

Write-Log "installed release $Release to $InstallRoot and wrote $($Policy.Count) policy values to $PolicyKey"
exit 0
